#include<bits/stdc++.h>

using namespace std;

vector<long long> mem;
long long f(long long x){
  if(mem[x]!=-1){return mem[x];}
  if(x==0){return 0;}
  if(x==1){return 1;}
  mem[x]=f(x-2)+f(x-1);
  return mem[x];
}

int main(){
  mem.resize(85);
  for(auto &nx : mem){nx=-1;}
  cout << f(80) << "\n";
  return 0;
}
